"use client"; // Required for Swiper.js in Next.js App Router

import Image from "next/image";
import { Swiper, SwiperSlide } from "swiper/react";
import { Navigation, Pagination, Autoplay } from "swiper/modules";
import "swiper/css";
import "swiper/css/navigation";
import "swiper/css/pagination";
import { Star, ArrowLeft, ArrowRight, Quote } from "lucide-react";

export default function TestimonialsSection() {
  const testimonials = [
    {
      id: 1,
      name: "Theresa Webb",
      role: "Tech Enthusiast",
      text: "I've been using AllSpark for several months now, and I'm extremely impressed with the ease of customization it offers. The wide range of templates.",
      image: "/images/testimonial.png",
      rating: 4,
    },
    {
      id: 2,
      name: "Theresa Webb",
      role: "Tech Enthusiast",
      text: "I've been using AllSpark for several months now, and I'm extremely impressed with the ease of customization it offers. The wide range of templates.",
      image: "/images/testimonial.png",
      rating: 4,
    },
    {
      id: 3,
      name: "Theresa Webb",
      role: "Tech Enthusiast",
      text: "I've been using AllSpark for several months now, and I'm extremely impressed with the ease of customization it offers. The wide range of templates.",
      image: "/images/testimonial.png",
      rating: 4,
    },
    {
      id: 5,
      name: "Theresa Webb",
      role: "Tech Enthusiast",
      text: "I've been using AllSpark for several months now, and I'm extremely impressed with the ease of customization it offers. The wide range of templates.",
      image: "/images/testimonial.png",
      rating: 4,
    },
  ];

  return (
    <section className="py-24 bg-gray-100 pt-60">
      <div className="mx-auto max-w-7xl px-6 text-center">
        {/* Title */}
        <div className="flex items-center justify-center space-x-3 text-blue-500 font-semibold text-sm uppercase">
          <ArrowLeft className="h-5 w-5" />
          <span>Testimonials</span>
          <ArrowRight className="h-5 w-5" />
        </div>
        <div className="relative">
          <h2 className="mt-5 !mb-20  text-4xl font-bold text-gray-900">
            Our Latest Client Feedback
          </h2>
           <div className="mt-8 flex absolute right-0 top-0 items-center justify-center space-x-4">
              {/* Previous Button */}
              <button className=" flex h-8 w-8 items-center justify-center rounded-full border border-gray-300 bg-white text-gray-700 hover:bg-gray-100 hover:border-blue-500 hover:text-blue-500 transition">
              <ArrowLeft className="text-blue-500 h-5 w-5" />
              </button>
        
              {/* Next Button */}
              <button className=" flex h-8 w-8 items-center justify-center rounded-full bg-blue-500 text-white hover:bg-blue-600 transition">
                <ArrowRight className="h-5 w-5" />
              </button>
            </div>
        </div>
        {/* Swiper Carousel */}
        <div className="mt-10">
          <Swiper
            modules={[Navigation, Pagination, Autoplay]}
            spaceBetween={20}
            slidesPerView={1}
            breakpoints={{
              640: { slidesPerView: 1 },
              768: { slidesPerView: 2 },
              1024: { slidesPerView: 3 },
            }}
            navigation={{
              nextEl: ".swiper-button-next",
              prevEl: ".swiper-button-prev",
            }}
            pagination={{ clickable: true }}
            autoplay={{ delay: 3000, disableOnInteraction: false }}
            className="swiper-container"
          >
            {testimonials.map((testimonial, index) => (
              <SwiperSlide key={testimonial.id}>
                <div
                  className={`p-6 rounded-lg shadow-lg transition-all ${
                    index === 1 ? "bg-blue-600 text-white" : "bg-white"
                  }`}
                >
                  {/* Star Ratings */}
                  <div className="flex justify-center space-x-1 mb-3">
                    {[...Array(5)].map((_, i) => (
                      <Star
                        key={i}
                        className={`h-5 w-5 ${
                          i < testimonial.rating
                            ? "text-yellow-400"
                            : index === 1
                            ? "text-gray-300"
                            : "text-gray-400"
                        }`}
                      />
                    ))}
                  </div>

                  {/* Testimonial Text */}
                  <p className="text-sm">{testimonial.text}</p>

                  {/* User Info */}
                  <div className="mt-4 flex items-center space-x-3">
                    <Image
                      src={testimonial.image}
                      alt={testimonial.name}
                      width={40}
                      height={40}
                      className="h-10 w-10 rounded-full"
                    />
                    <div>
                      <h3 className="font-semibold">{testimonial.name}</h3>
                      <p className="text-xs text-gray-500">
                        {testimonial.role}
                      </p>
                    </div>
                    <Quote className="ml-auto h-6 w-6 text-gray-300" />
                  </div>
                </div>
              </SwiperSlide>
            ))}
          </Swiper>

          {/* Navigation Buttons */}
        </div>
      </div>
    </section>
  );
}
