"use client"; // Required for Next.js App Router

import Image from "next/image";


export default function AboutSection() {
  return (
    <section className="relative bg-blue-600 py-28 text-white">
      <div className="mx-auto max-w-7xl flex flex-col-reverse  justify-between gap-10 px-6 lg:flex-row">
        {/* Left Side - Images */}
        <div className="relative flex w-full max-w-lg">
          {/* Main Image */}
          <div className="relative w-full overflow-hidden rounded-xl">
            <Image
               src="/images/faqThumb1.png"
              alt="AI Technology"
              width={500}
              height={400}
              className="rounded-xl"
            />
          </div>
          {/* Overlay Image */}
          <div className="absolute bottom-[-30px] right-[-40px] ">
            <Image
              src="/images/faqThumb2.png"
              alt="Team Collaboration"
              width={300}
              height={250}
              className=""
            />
          </div>

          {/* Circular Explore More Button */}
          <div className="absolute top-0 right-4 flex items-center justify-center w-24 h-24 rounded-full border-2 border-white text-white text-xs uppercase tracking-wide">
          <Image
              src="/images/aboutShape2.png"
              alt="Team Collaboration"
             fill
              className=""
            />
          </div>
        </div>

        {/* Right Side - Content */}
        <div className="w-full max-w-lg text-center lg:text-left">
          {/* About Company Label */}
          <div className="mb-2 flex  justify-end lg:justify-start space-x-2 text-sm font-semibold uppercase tracking-wide">
            <span className="text-white">← ABOUT COMPANY →</span>
          </div>

          {/* Main Heading */}
          <h1 className="text-4xl font-bold !leading-normal sm:text-4xl">
            Supercharge Your Business with AI Technology
          </h1>

          {/* Description */}
          <p className="mt-4 text-base text-white/80">
            Transform your business with next-gen AI, intelligent automation,
            and scalable digital solutions tailored to drive growth, efficiency,
            and innovation.
          </p>

          {/* Service Badges */}
          <div className="mt-6 flex flex-wrap justify-center gap-4 lg:justify-start">
            <div className="flex items-center text-sm space-x-2 rounded-lg bg-white/10 px-2 pr-4 py-2 text-white">
            <div className="relative h-full w-10 flex justify-center items-center rounded-md bg-white ">
                <Image
                src={"/images/aboutIcon1_1 (1).svg"}
                alt="Product Design"
                width={30}
                height={30}
                />
              </div>
              <span>Back-End <br/>Development</span>
            </div>
            <div className="flex items-center space-x-2 text-sm rounded-lg bg-white/10 px-2 pr-4 py-2 text-white">
              <div className="relative h-full w-10 flex justify-center items-center rounded-md bg-white ">
                <Image
                src={"/images/aboutIcon1_1 (1).svg"}
                alt="Product Design"
                width={30}
                height={30}
                />
              </div>
              <span>Product <br/>Design</span>
            </div>
          </div>

          {/* Statistics */}
          <div className="mt-8 grid grid-cols-3 text-center lg:text-left">
            {[
              { number: "20.5 k", label: "Projects Done" },
              { number: "100.5 k", label: "Happy Clients" },
              { number: "150.5 k", label: "Team Members" },
            ].map((stat, index) => (
              <div key={index}>
                <h2 className="text-2xl font-bold">{stat.number}</h2>
                <p className="text-sm text-white/80">{stat.label}</p>
              </div>
            ))}
          </div>

          {/* Explore More Button */}
         
        </div>
      </div>
    </section>
  );
}
