"use client"; // Necessary for Swiper to work properly in Next.js App Router

import React from "react";
import { Swiper, SwiperSlide } from "swiper/react";
import { Navigation, Pagination, Autoplay } from "swiper/modules";
import "swiper/css";
import "swiper/css/navigation";
import "swiper/css/pagination";

import { Button } from "@/components/ui/button"; // Import from shadcn/ui
import {
  ArrowLeft,
  ArrowRight,
  BarChart,
  Cloud,
  Settings,
  Code,
} from "lucide-react"; // Lucide Icons

export default function ServicesSection() {
  const services = [
    {
      id: 1,
      title: "Al & Machine Learning",
      description:
        "Al-powered chatbots & virtual assistants for automation. Machine learning model development & data analysis. Intelligent process automation & NLP solutions.",
      icon: <BarChart className="h-10 w-10 text-blue-500" />,
    },
    {
      id: 2,
      title: "Web & App Development",
      description:
        "Full-stack web & mobile app development. API integration & custom automation solutions. Progressive Web Apps (PWAS) & headless CMS solutions.",
      icon: <Cloud className="h-10 w-10 text-blue-500" />,
    },
    {
      id: 3,
      title: "Custom Software Development",
      description:
        "SaaS-based web & mobile app development. UI/UX design, wireframing, and prototyping. Custom marketplace & eCommerce solutions.",
      icon: <Settings className="h-10 w-10 text-blue-500" />,
    },
    {
      id: 4,
      title: "Ecommerce Development",
      description:
        "Shopify & WooCommerce store development. Marketplace integration, custom product configurators & subscription-based models.",
      icon: <Code className="h-10 w-10 text-blue-500" />,
    },
    {
      id: 5,
      title: "Digital Marketing",
      description:
        "SEO optimization & lead generation campaigns. Branding, content marketing & social media growth. Paid ad management.",
      icon: <Code className="h-10 w-10 text-blue-500" />,
    },
    {
      id: 6,
      title: "Social Media Marketing",
      description:
        "Paid ad campaigns. Expert content creation & social media management. Proactive community management & dynamic engagement strategies.",
      icon: <Code className="h-10 w-10 text-blue-500" />,
    },
    {
      id: 7,
      title: "Cloud & DevOps Solutions",
      description:
        "Cloud migration & infrastructure management CI/CD pipelines & automation setup. Kubernetes & containerization for scalable applications.",
      icon: <Code className="h-10 w-10 text-blue-500" />,
    },
    {
      id: 8,
      title: "BPO & Tech-Enabled Services",
      description:
        "Customer support & live chat outsourcing. Email marketing & campaign management. Data entry, processing, and document management.",
      icon: <Code className="h-10 w-10 text-blue-500" />,
    },
   
  ];

  return (
    <section className="py-28">
      <div className="mx-auto max-w-7xl px-6 text-start">
        {/* Title Section */}
        <div className="flex items-center justify-start space-x-3">
          <ArrowLeft className="text-blue-500 h-5 w-5" />
          <span className="text-blue-500 font-semibold uppercase text-sm">
            Our Services
          </span>
          <ArrowRight className="text-blue-500 h-5 w-5" />
        </div>
        <div className="relative">
          <h2 className="mt-3 text-4xl font-semibold text-gray-900">
            What We Do Best - AI-Powered <br /> Services
          </h2>
 
    <div className="mt-8 flex absolute right-0 top-0 items-center justify-center space-x-4">
      {/* Previous Button */}
      <button className=" flex h-8 w-8 items-center justify-center rounded-full border border-gray-300 bg-white text-gray-700 hover:bg-gray-100 hover:border-blue-500 hover:text-blue-500 transition">
      <ArrowLeft className="text-blue-500 h-5 w-5" />
      </button>

      {/* Next Button */}
      <button className=" flex h-8 w-8 items-center justify-center rounded-full bg-blue-500 text-white hover:bg-blue-600 transition">
        <ArrowRight className="h-5 w-5" />
      </button>
    </div>
  

        </div>
        {/* Swiper Carousel */}
        <div className="mt-10">
          <Swiper
            modules={[Navigation, Pagination, Autoplay]}
            spaceBetween={20}
            slidesPerView={1}
            breakpoints={{
              640: { slidesPerView: 1 },
              768: { slidesPerView: 2 },
              1024: { slidesPerView: 3 },
              1280: { slidesPerView: 4 },
            }}
            navigation={{
              nextEl: ".swiper-button-next",
              prevEl: ".swiper-button-prev",
            }}
            pagination={{ clickable: true }}
            autoplay={{ delay: 3000, disableOnInteraction: false }}
            className="swiper-container"
          >
            {services.map((service) => (
              <SwiperSlide key={service.id}>
                <div className="rounded-lg border border-gray-200 bg-white p-6 shadow-md transition-all hover:shadow-lg">
                  {/* Icon */}
                  <div className="mb-4 flex h-16 w-16 items-center justify-center rounded-xl bg-blue-100">
                    {service.icon}
                  </div>
                  {/* Title */}
                  <h3 className="text-lg font-semibold text-gray-900">
                    {service.title}
                  </h3>
                  {/* Description */}
                  <p className="mt-2 text-sm text-gray-600">
                    {service.description}
                  </p>
                  {/* Read More Button */}
                  <Button variant="outline" className="mt-4">
                    Read more <ArrowRight className="ml-2 h-4 w-4" />
                  </Button>
                </div>
              </SwiperSlide>
            ))}
          </Swiper>

          {/* Navigation Buttons */}
        </div>
      </div>
    </section>
  );
}
