"use client"; // Required for Next.js App Router

import Image from "next/image";
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/components/ui/accordion";
import { ArrowLeft, ArrowRight } from "lucide-react";

export default function FaqSection() {
  return (
    <section className="py-16 ">
      <div className="mx-auto max-w-6xl px-6 flex flex-col md:flex-row items-center justify-between gap-10">
        {/* Left Side - Images */}
        <div className="relative w-full max-w-md">
          {/* Main Image */}
          <div className="overflow-hidden rounded-3xl ">
            <Image
              src="/images/faqThumb1.png"
              alt="Team Working"
              width={400}
              height={400}
           
            />
          </div>
          {/* Overlay Image */}
          <div className="absolute bottom-[-50px] right-[-30px] ">
            <Image
              src="/images/faqThumb2.png"
              alt="Team Discussion"
              width={280}
              height={250}
           
            />
          </div>
        </div>

        {/* Right Side - FAQ */}
        <div className="w-full max-w-lg">
          {/* FAQ Label */}
          <div className="mb-2 flex items-center space-x-2 text-sm font-semibold uppercase tracking-wide text-blue-500">
            <ArrowLeft className="h-5 w-5" />
            <span>FAQ</span>
            <ArrowRight className="h-5 w-5" />
          </div>

          {/* Main Heading */}
          <h2 className="text-3xl font-bold !leading-relaxed text-gray-900">
            Prioritize Your Sites Safety And Security
          </h2>

          {/* FAQ Accordion */}
          <Accordion type="single" collapsible className="mt-6 space-y-3">
            <AccordionItem value="item-1">
              <AccordionTrigger>Where Should I Incorporate My Business?</AccordionTrigger>
              <AccordionContent>
                The best location for incorporating a business depends on the type of business, tax benefits, and legal regulations.
              </AccordionContent>
            </AccordionItem>

            <AccordionItem value="item-2">
              <AccordionTrigger>How Long Should A Business Plan Be?</AccordionTrigger>
              <AccordionContent>
                A good business plan is typically between 15-25 pages, covering all essential areas such as market analysis, financials, and projections.
              </AccordionContent>
            </AccordionItem>

            <AccordionItem value="item-3">
              <AccordionTrigger className="text-blue-600">What is Included In Your Services?</AccordionTrigger>
              <AccordionContent>
                There are many variations of passages of Lorem Ipsum available, but the majority have suffered alteration in some form, by injected humor or randomized words.
              </AccordionContent>
            </AccordionItem>

            <AccordionItem value="item-4">
              <AccordionTrigger>What Type Of Company Is Measured?</AccordionTrigger>
              <AccordionContent>
                We work with startups, mid-sized companies, and enterprises to optimize security and scalability.
              </AccordionContent>
            </AccordionItem>
          </Accordion>
        </div>
      </div>
    </section>
  );
}
